import * as Print from 'expo-print';
import * as Sharing from 'expo-sharing';
import * as FileSystem from 'expo-file-system/legacy';
import * as DocumentPicker from 'expo-document-picker';
import { rupees, type Invoice, type Payment } from '@garage/shared';
import type { Api } from './api';

/** Escape all customer and garage text before embedding it in invoice HTML. */
function escape(value: string) {
  return value.replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]!);
}

/** Generate a printable immutable invoice snapshot with payment and GST details. */
export function invoiceHtml(invoice: Invoice, payments: Payment[]) {
  const paid = payments.filter(v => v.invoiceId === invoice.id).reduce((sum, v) => sum + v.amountPaise, 0);
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><title>${escape(invoice.number)}</title>
    <style>body{font-family:Arial,sans-serif;color:#142b43;padding:32px;line-height:1.6}h1{font-size:26px}table{border-collapse:collapse;width:100%}th,td{border-bottom:1px solid #bbc9d4;padding:10px;text-align:left}.total{font-weight:bold}footer{margin-top:32px}</style></head><body>
    <h1>${escape(invoice.garage.name)}</h1><p>${escape(invoice.garage.address)}<br>${escape(invoice.garage.phone)}${invoice.garage.gstin ? `<br>GSTIN: ${escape(invoice.garage.gstin)}` : ''}</p>
    <h2>Invoice ${escape(invoice.number)}</h2><p>Date: ${invoice.date}<br>Customer: ${escape(invoice.customerName)}<br>Phone: ${escape(invoice.phone)}<br>Bike: ${escape(invoice.registration)}</p>
    <table><caption>Parts and labour (tax-exclusive)</caption><thead><tr><th scope="col">Description</th><th scope="col">Qty</th><th scope="col">Rate</th><th scope="col">Amount</th></tr></thead><tbody>
    ${invoice.parts.map(part => `<tr><td>${part.category === 'accessory' ? 'Accessory' : 'Part'}: ${escape(part.name)} (${escape(part.sku)})${part.fitmentNote ? `<br>${escape(part.fitmentNote)}` : ''}</td><td>${part.quantity}</td><td>${rupees(part.pricePaise)}</td><td>${rupees(part.quantity * part.pricePaise)}</td></tr>`).join('')}
    <tr><td>Labour</td><td>1</td><td>${rupees(invoice.laborPaise)}</td><td>${rupees(invoice.laborPaise)}</td></tr></tbody></table>
    <p>Subtotal: ${rupees(invoice.subtotalPaise)}<br>GST (${invoice.gstBasisPoints / 100}%): ${rupees(invoice.taxPaise)}<br>
    <span class="total">Total: ${rupees(invoice.totalPaise)}</span><br>Paid: ${rupees(paid)}<br>Outstanding: ${rupees(invoice.totalPaise - paid)}</p>
    <footer>Thank you for servicing your bike with us.<br>GST is shown as a combined tax amount. Confirm jurisdiction-specific tax treatment with your accountant.</footer></body></html>`;
}

/** Share a generated PDF only after an explicit user action, then remove its temporary file. */
export async function shareInvoice(invoice: Invoice, payments: Payment[]) {
  if (!await Sharing.isAvailableAsync()) throw new Error('File sharing is unavailable on this device');
  const file = await Print.printToFileAsync({ html: invoiceHtml(invoice, payments) });
  try { await Sharing.shareAsync(file.uri, { mimeType: 'application/pdf', dialogTitle: invoice.number }); }
  finally { await FileSystem.deleteAsync(file.uri, { idempotent: true }); }
}

/** Export a sensitive business backup through the native share sheet and clean up local temporary storage. */
export async function shareBackup(api: Api) {
  if (!await Sharing.isAvailableAsync() || !FileSystem.cacheDirectory) throw new Error('Backup sharing requires an Android device');
  const data = await api.request<unknown>('/backup');
  const path = `${FileSystem.cacheDirectory}garage-backup-${Date.now()}.json`;
  try {
    await FileSystem.writeAsStringAsync(path, JSON.stringify(data));
    await Sharing.shareAsync(path, { mimeType: 'application/json', dialogTitle: 'Save garage backup securely' });
  } finally { await FileSystem.deleteAsync(path, { idempotent: true }); }
}

/** Import a bounded JSON backup; the server validates it and refuses to overwrite existing business data. */
export async function restoreFromFile(api: Api) {
  const result = await DocumentPicker.getDocumentAsync({ type: 'application/json', copyToCacheDirectory: true });
  if (result.canceled) return null;
  const file = result.assets[0];
  try {
    if (!file.size || file.size > 10 * 1024 * 1024) throw new Error('Choose a non-empty JSON backup smaller than 10 MB');
    const text = await FileSystem.readAsStringAsync(file.uri);
    return await api.request<{ restored: number }>('/restore', 'POST', JSON.parse(text));
  } finally { await FileSystem.deleteAsync(file.uri, { idempotent: true }); }
}
